/* Local design prototype. No network, real account, payment, STT, printing or app IPC. */
'use strict';
const paths={live:'<rect x="3" y="5" width="18" height="14" rx="3"/><path d="M8 9v6m4-8v10m4-8v6"/>',orders:'<path d="M7 3h10l3 4v14H4V7zM7 3v5h10V3M8 12h8m-8 4h6"/>',chart:'<path d="M4 3v17h17M8 16v-5m5 5V7m5 9V4"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',devices:'<rect x="2" y="4" width="14" height="11" rx="2"/><path d="M7 19h5m-3-4v4"/><rect x="17" y="9" width="5" height="12" rx="1"/>',sliders:'<path d="M5 3v5m0 4v9M12 3v10m0 4v4M19 3v3m0 4v11"/><path d="M2 8h6v4H2zM9 13h6v4H9zM16 6h6v4h-6z"/>',settings:'<path d="m9 3-1 3-3 1 1 3-2 2 2 2-1 3 3 1 1 3h6l1-3 3-1-1-3 2-2-2-2 1-3-3-1-1-3z"/><circle cx="12" cy="12" r="3"/>',chevron:'<path d="m9 6 6 6-6 6"/>',search:'<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 5 5"/>',moon:'<path d="M20 14a8.6 8.6 0 0 1-10-10 9 9 0 1 0 10 10Z"/>',bell:'<path d="M6 9a6 6 0 0 1 12 0v6l2 2H4l2-2zm4 11h4"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M7 2v6m10-6v6M3 11h18M7 15h3m4 0h3"/>',mic:'<rect x="9" y="2" width="6" height="13" rx="3"/><path d="M5 10v2a7 7 0 0 0 14 0v-2m-7 9v3m-4 0h8"/>',cursor:'<path d="m5 3 15 9-7 1-4 7z"/>',refresh:'<path d="M20 7v5h-5M4 17v-5h5"/><path d="M6 6a8 8 0 0 1 13 2M5 16a8 8 0 0 0 13 2"/>',check:'<path d="m5 12 4 4L19 6"/>',shield:'<path d="m12 3 8 3v6c0 5-8 9-8 9s-8-4-8-9V6z"/><path d="m8 12 3 3 5-6"/>',download:'<path d="M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5"/>',info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v6m0-10v1"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>'};
function icons(root=document){root.querySelectorAll('[data-icon]').forEach(el=>{el.innerHTML=`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${paths[el.dataset.icon]||paths.info}</svg>`;});}
const $=id=>document.getElementById(id);
const money=n=>Math.round(n).toLocaleString('ko-KR');
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const comments=[{id:'c1',name:'하늘',text:'27번 아이보리 2개요 🤍',qty:2,time:'20:24:16',color:''},{id:'c2',name:'봄날',text:'가방 무게가 가벼운가요?',qty:1,time:'20:24:12',color:'peach'},{id:'c3',name:'지니',text:'저도 27번 하나 구매할게요!',qty:1,time:'20:24:09',color:'sage'},{id:'c4',name:'소소한 일상',text:'아이보리 컬러 정말 예쁘네요',qty:1,time:'20:24:05',color:'lavender'},{id:'c5',name:'다온',text:'27번 하나 추가 부탁드려요',qty:1,time:'20:23:58',color:'rose'},{id:'c6',name:'라온',text:'배송은 언제 시작될까요?',qty:1,time:'20:23:51',color:'sand'}];
let sales=[{id:1008,buyer:'민트',product:'데일리 코튼 셔츠',sku:'026',qty:1,price:32000,status:'확정',time:'20:23',memo:'화이트 / M',evidence:'26번 화이트 하나요'},{id:1007,buyer:'유리',product:'클래식 캔버스 토트백',sku:'027',qty:1,price:29000,status:'확정',time:'20:21',memo:'아이보리',evidence:'27번 한 개 구매합니다'},{id:1006,buyer:'봄날',product:'메리노 울 머플러',sku:'025',qty:1,price:24000,status:'보류',time:'20:18',memo:'구매자 확인 필요',evidence:'머플러 가격 다시 알려주세요'},{id:1005,buyer:'윤슬',product:'클래식 캔버스 토트백',sku:'027',qty:2,price:29000,status:'확정',time:'20:16',memo:'아이보리 2개',evidence:'27번 두 개요'},{id:1004,buyer:'다온',product:'메리노 울 머플러',sku:'025',qty:1,price:24000,status:'확정',time:'20:12',memo:'오트밀',evidence:'25번 하나 구매할게요'},{id:1003,buyer:'지니',product:'데일리 코튼 셔츠',sku:'026',qty:1,price:32000,status:'보류',time:'20:10',memo:'옵션 확인 필요',evidence:'셔츠 사이즈를 고민 중이에요'},{id:1002,buyer:'소소한 일상',product:'데일리 코튼 셔츠',sku:'026',qty:2,price:32000,status:'확정',time:'20:07',memo:'화이트 / M, L',evidence:'26번 미디움 라지 하나씩요'},{id:1001,buyer:'라온',product:'메리노 울 머플러',sku:'025',qty:1,price:24000,status:'확정',time:'20:04',memo:'그레이',evidence:'25번 그레이 구매해요'}];
let state={view:'live',filter:'all',selected:'c1',audio:true,connected:true,theme:'light',compact:false,group:'date'};
let nextId=1009,undo=null,toastTimer=null,lastFocus=null,detailId=null;
function stats(){const done=sales.filter(s=>s.status==='확정');return{done,pending:sales.filter(s=>s.status==='보류'),amount:done.reduce((a,s)=>a+s.price*s.qty,0),qty:done.reduce((a,s)=>a+s.qty,0)};}
function statusChip(status){return `<span class="badge ${status==='확정'?'confirmed':'pending'}">${status==='확정'?'✓':'◷'} ${status}</span>`;}
function metric(label,value,note){return`<article class="metric-card"><span>${label}</span><strong>${value}</strong><small>${note}</small></article>`;}
function renderComments(){let q=$('commentSearch').value.trim().toLowerCase();const list=comments.filter(c=>(c.name+c.text).toLowerCase().includes(q));$('commentsList').innerHTML=list.length?list.map(c=>`<button class="comment-row ${state.selected===c.id?'selected':''}" data-comment="${c.id}" aria-pressed="${state.selected===c.id}"><span class="avatar ${c.color}">${esc(c.name[0])}</span><span class="comment-main"><span class="comment-top"><span class="comment-name">${esc(c.name)}</span><time class="comment-time">${c.time}</time></span><span class="comment-body">${esc(c.text)}</span>${state.selected===c.id?'<span class="comment-selected-label">✓ 판매 기록에 선택됨</span>':''}</span></button>`).join(''):'<div class="empty-state">검색 결과가 없어요.<br>다른 닉네임이나 단어로 찾아보세요.</div>';}
function selectComment(id){const c=comments.find(c=>c.id===id);if(!c)return;state.selected=id;$('selectedBuyer').textContent=c.name;$('selectedComment').textContent=c.text;$('quantity').value=c.qty;$('unitPrice').value=29000;$('saleMemo').value='';$('formError').hidden=true;renderComments();updateTotal();}
function updateTotal(){const rawPrice=$('unitPrice').value.trim(),rawQty=$('quantity').value.trim(),price=Number(rawPrice),qty=Number(rawQty);const valid=rawPrice!==''&&rawQty!==''&&Number.isInteger(price)&&price>=0&&price<=99999999&&Number.isInteger(qty)&&qty>=1&&qty<=999;$('composerTotal').innerHTML=`${valid?money(price*qty):'—'}<small>원</small>`;}
function renderSales(){const q=$('salesSearch').value.trim().toLowerCase();const filtered=sales.filter(s=>(state.filter==='all'||s.status===state.filter)&&`${s.buyer} ${s.product} ${s.id}`.toLowerCase().includes(q));$('salesTableBody').innerHTML=filtered.length?filtered.map(s=>`<tr><td class="order-id">VC-${s.id}</td><td><span class="table-buyer"><span class="avatar ${s.id%2?'sage':'peach'}">${esc(s.buyer[0])}</span>${esc(s.buyer)}</span></td><td class="table-product">${esc(s.product)}<small>NO. ${s.sku} · ${esc(s.memo||'옵션 메모 없음')}</small></td><td class="number">${s.qty}</td><td class="number money">${money(s.qty*s.price)}원</td><td>${statusChip(s.status)}</td><td class="order-id">${s.time}</td><td><button class="icon-button" data-detail="${s.id}" aria-label="VC-${s.id} ${esc(s.buyer)} 판매 상세"><span data-icon="chevron"></span></button></td></tr>`).join(''):'<tr><td colspan="8"><div class="empty-state">조건에 맞는 판매가 없어요.<br>검색어나 필터를 바꿔 주세요.</div></td></tr>';$('salesResultCount').textContent=`총 ${filtered.length}건 표시 · 전체 ${sales.length}건`;document.querySelectorAll('[data-filter]').forEach(b=>{b.classList.toggle('active',b.dataset.filter===state.filter);b.setAttribute('aria-pressed',String(b.dataset.filter===state.filter));});icons($('salesTableBody'));}
function renderStats(){const s=stats();$('liveAmount').textContent=money(s.amount)+'원';$('liveConfirmed').innerHTML=`${s.done.length}<span>건</span>`;$('livePending').innerHTML=`${s.pending.length}<span>건</span>`;$('navSalesCount').textContent=sales.length;$('navPendingCount').textContent=s.pending.length;$('salesMetrics').innerHTML=metric('확정 판매액',money(s.amount)+'원','전체 샘플 회차 · 보류 제외')+metric('확정 주문',s.done.length+'건','판매 확정 상태 기준')+metric('보류 주문',s.pending.length+'건','추가 확인이 필요해요')+metric('전체 주문',sales.length+'건','시안의 모든 샘플 주문');$('recentSales').innerHTML=sales.slice(0,2).map(v=>`<button class="recent-sale" data-detail="${v.id}"><span class="recent-check">${v.status==='확정'?'✓':'◷'}</span><div><strong>${esc(v.buyer)}</strong><small>${v.time} · ${v.status} · NO. ${v.sku}</small></div><span>${money(v.price*v.qty)}원</span></button>`).join('');$('settlementAmount').innerHTML=money(s.amount)+'<small>원</small>';$('settlementMetrics').innerHTML=metric('확정 주문',s.done.length+'건','보류 주문은 집계에서 제외')+metric('주문당 평균',money(s.done.length?s.amount/s.done.length:0)+'원','확정 판매액 ÷ 확정 주문 수')+metric('확인할 보류',s.pending.length+'건','확정하면 정산에 반영됩니다');$('groupAmount').textContent=money(s.amount)+'원';$('groupCount').textContent=s.done.length+'건';$('groupQuantity').textContent=s.qty+'개';const products={};s.done.forEach(v=>products[v.product]=(products[v.product]||0)+v.qty*v.price);const items=Object.entries(products).sort((a,b)=>b[1]-a[1]);const max=Math.max(...items.map(v=>v[1]),1);$('productChart').innerHTML=items.length?items.map(([name,sum])=>`<div class="bar-row"><div class="bar-labels"><span>${esc(name)}</span><strong>${money(sum)}원</strong></div><div class="bar-track" role="img" aria-label="${esc(name)} ${money(sum)}원"><div class="bar-fill" style="width:${sum/max*100}%"></div></div></div>`).join(''):'<div class="empty-state">확정 주문이 아직 없습니다.</div>';renderSales();}
function view(name,focus=true){if(!['live','sales','settlement'].includes(name))name='live';state.view=name;['live','sales','settlement'].forEach(v=>$(v+'View').hidden=v!==name);document.querySelectorAll('.nav-item[data-view]').forEach(b=>{b.classList.toggle('active',b.dataset.view===name);b.setAttribute('aria-current',b.dataset.view===name?'page':'false');});$('breadcrumbTitle').textContent={live:'라이브 작업대',sales:'판매 내역',settlement:'정산'}[name];history.replaceState(null,'','#'+name);if(focus)$('main').focus({preventScroll:true});window.scrollTo(0,0);}
function notify(text,canUndo=false){clearTimeout(toastTimer);$('toastText').textContent=text;$('undoButton').hidden=!canUndo;$('toast').hidden=false;toastTimer=setTimeout(()=>$('toast').hidden=true,canUndo?18000:7000);}
function formValues(){const priceText=$('unitPrice').value.trim(),qtyText=$('quantity').value.trim(),price=Number(priceText),qty=Number(qtyText);if(priceText===''||qtyText===''||!Number.isInteger(price)||price<0||price>99999999||!Number.isInteger(qty)||qty<1||qty>999){$('formError').textContent='단가는 0~99,999,999원, 수량은 1~999의 정수를 입력해 주세요. 빈값은 저장할 수 없습니다.';$('formError').hidden=false;return null;}return{price,qty};}
function addSale(status,reason=''){const values=formValues();if(!values)return;const c=comments.find(c=>c.id===state.selected);const sale={id:nextId++,buyer:c.name,product:'클래식 캔버스 토트백',sku:'027',qty:values.qty,price:values.price,status,time:'20:24',memo:[$('saleMemo').value.trim(),reason].filter(Boolean).join(' · ')||'아이보리',evidence:c.text};sales.unshift(sale);undo={kind:'create',id:sale.id};renderStats();$('formError').hidden=true;notify(`샘플 주문 VC-${sale.id} · ${sale.buyer} ${money(sale.price*sale.qty)}원 ${status}`,true);}
function openDialog(title,content,eyebrow='VOICECAP STUDIO'){lastFocus=document.activeElement;$('dialogTitle').textContent=title;$('dialogEyebrow').textContent=eyebrow;$('dialogContent').innerHTML=content;icons($('dialogContent'));if(!$('appDialog').open)$('appDialog').showModal();}
function closeDialog(){if($('appDialog').open)$('appDialog').close();}
function settings(){openDialog('편안한 작업 환경','<p class="dialog-copy">이 시안에서 테마와 정보 밀도를 바꿔 볼 수 있어요. 새로고침하면 기본값으로 돌아갑니다.</p><div class="setting-row"><div><strong>화면 테마</strong><small>업무 환경에 맞게 밝기를 선택하세요</small></div><select id="themeSelect" aria-label="화면 테마"><option value="light">라이트</option><option value="dark">다크</option></select></div><div class="setting-row"><div><strong>정보 밀도</strong><small>동일한 내용을 더 촘촘하게 표시합니다</small></div><select id="densitySelect" aria-label="정보 밀도"><option value="standard">표준</option><option value="compact">컴팩트</option></select></div><div class="setting-row"><div><strong>움직임 줄이기</strong><small>이 시안은 지속 애니메이션을 사용하지 않으며<br>OS의 모션 감소 설정도 따릅니다</small></div><span class="badge confirmed">지원</span></div><div class="dialog-actions"><button class="button primary" data-action="closeDialog">완료</button></div>','APPEARANCE');$('themeSelect').value=state.theme;$('densitySelect').value=state.compact?'compact':'standard';}
function setTheme(theme){state.theme=theme;document.body.classList.toggle('dark',theme==='dark');}
function connectionDialog(){openDialog('기기 및 연결',`<p class="dialog-copy">댓글 도우미는 Windows 앱 안에서 실행됩니다. 아래는 통합 상태 화면의 샘플이며 실제 장치를 제어하지 않습니다.</p><div class="connection-card"><div><strong>댓글 엔진</strong><small>@moment_studio · 내장 연결</small></div><span class="badge ${state.connected?'confirmed':'pending'}">${state.connected?'연결 정상':'연결 끊김'}</span></div><div class="connection-card"><div><strong>음성 인식</strong><small>마이크 · 로컬 STT</small></div><span class="badge ${state.audio?'confirmed':'neutral'}">${state.audio?'켜짐':'일시정지'}</span></div><div class="connection-card"><div><strong>클라우드 동기화</strong><small>샘플 전송 대기 0건</small></div><span class="badge ${state.connected?'confirmed':'pending'}">${state.connected?'연결 정상':'오프라인'}</span></div><div class="connection-card"><div><strong>프린터</strong><small>실제 출력은 시안에 연결하지 않았습니다</small></div><span class="badge neutral">미연결</span></div><div class="dialog-actions"><button class="button secondary" data-action="connection">${state.connected?'연결 끊김 체험':'샘플 다시 연결'}</button><button class="button primary" data-action="closeDialog">완료</button></div>`,'INTEGRATED SERVICES');}
function connectionToggle(){state.connected=!state.connected;$('mainConnection').classList.toggle('offline',!state.connected);$('mainConnection').innerHTML=`<i></i> ${state.connected?'통합 연결 정상':'오프라인 · 샘플'}`;$('statusText').textContent=state.connected?'댓글 엔진 내장 · 연결 정상':'댓글 엔진 내장 · 연결 끊김 (샘플)';$('statusDot').style.background=state.connected?'var(--teal)':'var(--amber)';document.querySelector('.live-label').innerHTML=state.connected?'<i></i> 수집 중':'<i></i> 일시정지';document.querySelector('.live-label').style.color=state.connected?'var(--teal)':'var(--amber)';connectionDialog();notify(state.connected?'샘플 연결이 복구되었습니다.':'오프라인 상태를 표시했습니다. 가짜 주문 조작은 계속 가능합니다.');}
function audioToggle(){state.audio=!state.audio;$('audioToggle').classList.toggle('on',state.audio);$('audioToggle').setAttribute('aria-checked',String(state.audio));$('audioLabel').textContent=state.audio?'마이크 입력 중':'음성 인식 일시정지';document.querySelector('.waveform').classList.toggle('paused',!state.audio);$('footerAudio').textContent=state.audio?'음성 인식 켜짐':'음성 인식 일시정지';notify(state.audio?'샘플 음성 인식을 켰습니다.':'샘플 음성 인식을 멈췄습니다.');}
function openDetail(id){const s=sales.find(v=>v.id===Number(id));if(!s)return;detailId=s.id;lastFocus=document.activeElement;$('detailTitle').textContent=`판매 상세 · VC-${s.id}`;$('detailContent').innerHTML=`<div class="detail-intro"><span class="avatar sage">${esc(s.buyer[0])}</span><div><strong>${esc(s.buyer)}</strong><small>2026.09.26 ${s.time} · 샘플 주문</small></div>${statusChip(s.status)}</div><div class="eyebrow">NO. ${s.sku}</div><h3>${esc(s.product)}</h3><div class="detail-amount">${money(s.price*s.qty)}원</div><div class="evidence">“${esc(s.evidence)}”<small>댓글 원문 근거 · 이 화면의 데이터는 모두 가상입니다</small></div><form id="detailForm"><div class="dialog-field"><label for="detailQty">수량</label><input class="text-input" id="detailQty" type="number" min="1" max="999" step="1" value="${s.qty}" required></div><div class="dialog-field"><label for="detailPrice">판매 단가 (원)</label><input class="text-input" id="detailPrice" type="number" min="0" max="99999999" step="1" value="${s.price}" required></div><div class="dialog-field"><label for="detailStatus">판매 상태</label><select id="detailStatus"><option ${s.status==='확정'?'selected':''}>확정</option><option ${s.status==='보류'?'selected':''}>보류</option></select></div><div class="dialog-field"><label for="detailMemo">메모</label><input class="text-input" id="detailMemo" maxlength="120" value="${esc(s.memo)}"></div><p id="detailError" class="form-error" role="alert" hidden></p><div class="dialog-actions"><button type="button" class="button secondary" data-action="closeDetail">취소</button><button type="submit" class="button primary">샘플 변경 저장</button></div></form><p class="form-note">인쇄 · AI 검증 · 캡처는 실제 앱에서 연결할 기능입니다.</p>`;if(!$('detailDialog').open)$('detailDialog').showModal();}
function saveDetail(event){event.preventDefault();const qtyText=$('detailQty').value.trim(),priceText=$('detailPrice').value.trim(),qty=Number(qtyText),price=Number(priceText);if(priceText===''||qtyText===''||!Number.isInteger(qty)||qty<1||qty>999||!Number.isInteger(price)||price<0||price>99999999){$('detailError').textContent='단가는 0~99,999,999원, 수량은 1~999의 정수여야 합니다. 빈값은 저장할 수 없습니다.';$('detailError').hidden=false;return;}const s=sales.find(v=>v.id===detailId);undo={kind:'edit',sale:{...s}};Object.assign(s,{qty,price,status:$('detailStatus').value,memo:$('detailMemo').value.trim()});$('detailDialog').close();renderStats();notify(`샘플 주문 VC-${s.id} 변경 사항을 저장했습니다.`,true);}
function exportCsv(onlyConfirmed=false){const query=$('salesSearch').value.trim().toLowerCase();const rows=onlyConfirmed?sales.filter(s=>s.status==='확정'):sales.filter(s=>state.view!=='sales'||((state.filter==='all'||s.status===state.filter)&&`${s.buyer} ${s.product} ${s.id}`.toLowerCase().includes(query)));const safe=v=>{let value=String(v);if(/^[=+@-]/.test(value))value="'"+value;return '"'+value.replace(/"/g,'""')+'"';};const content='\uFEFF'+[['주문번호','구매자','상품','수량','단가','합계','상태','메모'],...rows.map(s=>['VC-'+s.id,s.buyer,s.product,s.qty,s.price,s.qty*s.price,s.status,s.memo])].map(row=>row.map(safe).join(',')).join('\r\n');const url=URL.createObjectURL(new Blob([content],{type:'text/csv;charset=utf-8;'}));const a=document.createElement('a');a.href=url;a.download=`VoiceCAP_샘플_${onlyConfirmed?'확정판매':'판매목록'}_20260926.csv`;a.click();setTimeout(()=>URL.revokeObjectURL(url),2000);notify('가짜 데이터로 만든 샘플 CSV를 내려받았습니다.');}
function commands(){openDialog('원하는 화면으로 이동','<p class="dialog-copy">시안에서 구현된 화면입니다.</p><button class="command-option" data-command="live">라이브 작업대<span>Ctrl 1</span></button><button class="command-option" data-command="sales">판매 내역<span>Ctrl 2</span></button><button class="command-option" data-command="settlement">정산<span>Ctrl 3</span></button><button class="command-option" data-action="settings">앱 설정<span>테마 · 밀도</span></button>','QUICK NAVIGATION');}
const actions={settings,devices:connectionDialog,theme:()=>{setTheme(state.theme==='light'?'dark':'light');notify(state.theme==='dark'?'다크 테마로 변경했습니다.':'라이트 테마로 변경했습니다.');},audio:audioToggle,connection:connectionToggle,commands,closeDialog,closeDetail:()=>$('detailDialog').close(),pending:()=>{state.filter='보류';$('salesSearch').value='';renderSales();view('sales');},showConfirmed:()=>{state.filter='확정';$('salesSearch').value='';renderSales();view('sales');},clearFilters:()=>{state.filter='all';$('salesSearch').value='';renderSales();},commentReset:()=>{$('commentSearch').value='';renderComments();},hold:()=>{if(!formValues())return;openDialog('확인 후 처리하기','<p class="dialog-copy">샘플 주문을 보류로 남깁니다. 사유는 판매 상세에서 다시 확인할 수 있어요.</p><div class="dialog-field"><label for="holdReason">보류 사유</label><select id="holdReason"><option>구매자 확인 필요</option><option>상품 옵션 확인 필요</option><option>금액 확인 필요</option><option>중복 주문 확인 필요</option></select></div><div class="dialog-actions"><button class="button secondary" data-action="closeDialog">취소</button><button class="button primary" data-action="confirmHold">보류로 기록</button></div>','REVIEW LATER');},confirmHold:()=>{const reason=$('holdReason').value;closeDialog();addSale('보류',reason);},export:()=>exportCsv(false),exportConfirmed:()=>exportCsv(true),undo:()=>{if(!undo)return;if(undo.kind==='create')sales=sales.filter(s=>s.id!==undo.id);else{const index=sales.findIndex(s=>s.id===undo.sale.id);if(index>=0)sales[index]=undo.sale;}undo=null;renderStats();notify('마지막 샘플 변경을 되돌렸습니다.');},dismissToast:()=>$('toast').hidden=true,product:()=>openDialog('클래식 캔버스 토트백','<p class="dialog-copy">NO. 027 · MOMENT AUTUMN COLLECTION<br>아이보리 / FREE · 기본 단가 29,000원</p><div class="evidence">가볍고 탄탄한 캔버스 소재의 데일리 토트백입니다.<small>상품 이미지는 이 시안을 위해 작성한 SVG 일러스트입니다.</small></div><p class="dialog-copy">실제 앱에서는 상품 등록, 이미지 업로드, 가격 수정, 상품 전환과 판매 스냅샷을 지원합니다. 이 시안은 현재 상품 1개를 선택한 상태입니다.</p><div class="dialog-actions"><button class="button primary" data-action="closeDialog">확인</button></div>','PRODUCT INFORMATION'),session:()=>openDialog('현재 방송 회차','<div class="connection-card"><div><strong>모먼트 가을 컬렉션</strong><small>2026년 9월 26일 · 샘플 방송</small></div><span class="badge confirmed">선택됨</span></div><p class="dialog-copy">시안은 한 개의 샘플 회차를 사용합니다. 실제 앱에서는 새 방송, 이전 방송 이어 하기, 방송 종료를 제공하며 전송 대기 주문과 녹음 상태를 함께 확인합니다.</p><div class="dialog-actions"><button class="button primary" data-action="closeDialog">확인</button></div>','LIVE SESSION'),workspace:()=>openDialog('모먼트 스튜디오','<p class="dialog-copy">디자인 검토를 위한 가상 판매자 작업공간입니다. 실 계정이나 서버와 연결되어 있지 않습니다.</p><div class="connection-card"><div><strong>작업공간</strong><small>모먼트 스튜디오 / 샘플</small></div><span class="badge blue">선택됨</span></div><div class="dialog-actions"><button class="button primary" data-action="closeDialog">확인</button></div>'),profile:()=>openDialog('지은 매니저','<p class="dialog-copy">가상의 사용자 프로필입니다. 실제 앱에서는 계정, 작업공간, 구독, 개인정보, 백업 및 로그아웃을 이 영역에서 관리합니다.</p><div class="dialog-actions"><button class="button primary" data-action="closeDialog">확인</button></div>','SAMPLE PROFILE'),rules:()=>openDialog('인식 규칙 설계','<p class="dialog-copy">실제 앱에는 인식 단어 추가·수정·삭제, 구매 확정 및 정정 명령, 캡처 영역, 댓글 알림 설정이 이전됩니다.</p><div class="evidence">“구매 확정” → 판매 후보 확인<br>“27번 하늘님 2개” → 상품·구매자·수량 후보<small>이 시안은 음성을 듣거나 명령을 실행하지 않습니다.</small></div><p class="dialog-copy">전체 동작과 예외 상태는 05_SCREEN_SPECIFICATIONS.md의 W10을 참고하세요.</p><div class="dialog-actions"><button class="button primary" data-action="closeDialog">확인</button></div>','RECOGNITION RULES'),notifications:()=>openDialog('작업 알림',`<div class="connection-card"><div><strong>검토가 필요한 보류 ${stats().pending.length}건</strong><small>구매자와 상품 옵션을 확인해 주세요.</small></div><span class="badge pending">샘플</span></div><p class="dialog-copy">모든 알림은 디자인 시안의 가짜 데이터를 바탕으로 표시됩니다.</p><div class="dialog-actions"><button class="button secondary" data-action="closeDialog">닫기</button><button class="button primary" data-action="reviewFromDialog">보류 검토</button></div>`,'ACTIVITY'),reviewFromDialog:()=>{closeDialog();actions.pending();},decrease:()=>{$('quantity').value=Math.max(1,Number($('quantity').value||1)-1);updateTotal();},increase:()=>{$('quantity').value=Math.min(999,Number($('quantity').value||0)+1);updateTotal();}};
document.addEventListener('click',e=>{const btn=e.target.closest('button');if(!btn)return;if(btn.dataset.action&&actions[btn.dataset.action])actions[btn.dataset.action]();if(btn.dataset.view)view(btn.dataset.view);if(btn.dataset.comment)selectComment(btn.dataset.comment);if(btn.dataset.detail)openDetail(btn.dataset.detail);if(btn.dataset.filter){state.filter=btn.dataset.filter;renderSales();}if(btn.dataset.group){state.group=btn.dataset.group;$('settlementGroupLabel').textContent=state.group==='date'?'2026년 9월 26일':'모먼트 가을 컬렉션';document.querySelectorAll('[data-group]').forEach(b=>{b.classList.toggle('active',b.dataset.group===state.group);b.setAttribute('aria-pressed',String(b.dataset.group===state.group));});}if(btn.dataset.command){closeDialog();view(btn.dataset.command);}});
document.addEventListener('submit',e=>{if(e.target.id==='saleForm'){e.preventDefault();addSale('확정');}else if(e.target.id==='detailForm')saveDetail(e);});
document.addEventListener('change',e=>{if(e.target.id==='themeSelect')setTheme(e.target.value);if(e.target.id==='densitySelect'){state.compact=e.target.value==='compact';document.body.classList.toggle('compact',state.compact);}});
$('commentSearch').addEventListener('input',renderComments);$('salesSearch').addEventListener('input',renderSales);$('unitPrice').addEventListener('input',updateTotal);$('quantity').addEventListener('input',updateTotal);
document.addEventListener('keydown',e=>{if(e.ctrlKey&&e.key.toLowerCase()==='k'){e.preventDefault();if(!$('detailDialog').open)commands();}if((e.ctrlKey||e.metaKey)&&e.key==='Enter'&&state.view==='live'&&!$('appDialog').open&&!$('detailDialog').open&&$('saleForm').contains(document.activeElement)){e.preventDefault();$('saleForm').requestSubmit();}if(e.ctrlKey&&['1','2','3'].includes(e.key)&&!$('appDialog').open&&!$('detailDialog').open){e.preventDefault();view(['live','sales','settlement'][Number(e.key)-1]);}});
['appDialog','detailDialog'].forEach(id=>$(id).addEventListener('close',()=>{if(lastFocus&&document.contains(lastFocus))lastFocus.focus();}));
window.addEventListener('hashchange',()=>view(location.hash.slice(1),false));
icons();document.querySelectorAll('.nav-item').forEach(button=>{const label=button.querySelector('span:nth-child(2)')?.textContent;if(label){button.setAttribute('aria-label',label);button.title=label;}});document.querySelector('.waveform').innerHTML=Array.from({length:40},(_,i)=>`<span style="height:${5+Math.abs(Math.sin(i*1.7)*Math.cos(i*.33))*29}px"></span>`).join('');renderComments();renderStats();updateTotal();view(location.hash.slice(1)||'live',false);
